def transform(grid):
    """
    Cells with value 8 become 3 if adjacent to a 6 (horizontally or vertically).
    Otherwise, 8 stays 8, and 6 stays 6.
    """
    rows = len(grid)
    cols = len(grid[0])
    result = []
    for r in range(rows):
        new_row = []
        for c in range(cols):
            if grid[r][c] == 6:
                new_row.append(6)
            elif grid[r][c] == 8:
                # Check 4 neighbors for 6
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] == 6:
                            new_row.append(3)
                            break
                else:
                    new_row.append(8)
            else:
                # Other values stay the same
                new_row.append(grid[r][c])
        result.append(new_row)
    return result

