def transform3(grid):
    """8->3 when between 6s, so 5->3 when between 2s (fixed color 3)"""
    bg = 5
    marker = 2

    result = [[0]*len(grid[0]) for _ in range(len(grid))]

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == marker:
                result[r][c] = marker
            else:
                # Check horiz between marker
                left = any(grid[r][k] == marker for k in range(c))
                right = any(grid[r][k] == marker for k in range(c+1, len(grid[0])))

                # Check vert between marker
                above = any(grid[k][c] == marker for k in range(r))
                below = any(grid[k][c] == marker for k in range(r+1, len(grid)))

                if (left and right) or (above and below):
                    result[r][c] = 3
                else:
                    result[r][c] = bg

    return result

